"""Write OUTPT block data."""
def _write_outpt(parameters: Any) -> object {
    outpt = parameters["react"]["output"];
    values = [outpt["format"]];
    values += [x for x in outpt["shape"][:3]] if ("shape" in outpt) else [];
    out = ["{}\n".format(" ".join(str(x) for x in values))];
    return out;
}

test_blocks:
test "t0" {
    assert (_write_outpt({"react": {"output": {"format": 1}}}) == ["1\n"]);;
}

test "t1" {
    assert (_write_outpt({"react": {"output": {"format": "xyz"}}}) == ["xyz\n"]);;
}

test "t2" {
    assert (_write_outpt({"react": {"output": {"format": "xyz"}}}) == ["xyz\n"]);;
}

test "t3" {
    assert (_write_outpt({"react": {"output": {"format": 2}}}) == ["2\n"]);;
}

test "t4" {
    assert (_write_outpt({"react": {"output": {"format": "ascii"}}}) == ["ascii\n"]);;
}

test "t5" {
    assert (
        _write_outpt({"react": {"output": {"format": "ascii", "shape": (100, 10, 5)}}})
        == ["ascii 100 10 5\n"]
    );;
}

